mapper.select:
SELECT id, operator_id, operator_name, operation_type, target_type, target_id, request_ip, request_method, request_uri, operation_detail, create_time, last_modify_time FROM operation_logs WHERE 1 = 1
AND operation_type = #{operationType}
AND ( operator_name ILIKE CONCAT('%', #{keyword}, '%') OR operation_type ILIKE CONCAT('%', #{keyword}, '%') OR target_type ILIKE CONCAT('%', #{keyword}, '%') OR operation_detail ILIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM operation_logs WHERE 1 = 1
AND operation_type = #{operationType}
AND ( operator_name ILIKE CONCAT('%', #{keyword}, '%') OR operation_type ILIKE CONCAT('%', #{keyword}, '%') OR target_type ILIKE CONCAT('%', #{keyword}, '%') OR operation_detail ILIKE CONCAT('%', #{keyword}, '%') )
